import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { PlaneGeometry, Mesh } = THREE;

  // Texture source rect: 512x320 -> aspect 1.6
  const cardWidth = 2;
  const cardHeight = cardWidth / (512 / 320); // 2 / 1.6 = 1.25

  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({ color: '#0b0b10' }); // surface placeholder
  const mesh = new Mesh(geometry, material);

  let loadedTexture = null;

  // Load texture asynchronously, update mesh when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      // Adjust geometry to match actual texture aspect ratio
      const actualAspect = tex.image.width / tex.image.height;
      if (Math.abs(actualAspect - cardWidth / cardHeight) > 0.01) {
        const newGeo = new PlaneGeometry(cardWidth, cardWidth / actualAspect);
        geometry.dispose();
        mesh.geometry = newGeo;
      }
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Cleanup: dispose geometry and texture
  mesh.userData.cleanup = () => {
    geometry.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // No GSAP timelines or primitives to clean
  };

  // No interaction handlers, no cinematic primitives
  return mesh;
}
